Definition g2w_words_exit (ra sp gp tp t0 t1 t2 s0 s1 a0 a3 a4 a5 a7 s3 s4 s5 s6 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (D n : Z) : machine_state -> Prop :=
  fun ms' => exists (a1' a2' a6' s2' s7' s8' s9' s10' s11' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1' a2' a3 a4 a5 a6' a7 s2' s3 s4 s5 s6 s7' s8' s9' s10' s11' t3 t4 t5 t6)
             F (Z_to_bv 64 0x12e9cc) fc None m' (seg_rom asegs)
    /\ munch [(D, D + 4 * n)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

