Lemma g2w_words : forall (k : nat) (j : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a0 a3 a4 a7 s2 s3 s4 s5 s6 s9 s10 s11 t3 t4 t5 t6 : word) F fc (m : mem) (SA DA n : Z),
  Z.of_nat k = n - j -> 0 <= j -> (1 <= k)%nat -> n < 2^26 ->
  0 < SA -> SA mod 4 = 0 -> SA + 4 * (n + 1) <= 2^47 -> 0 < DA -> DA mod 4 = 0 -> DA + 4 * n <= 2^47 ->
  (DA + 4 * n <= 0x7fff7000 \/ 0x10007fff8000 <= DA) ->
  wr_at asegs m SA (4 * (n + 1)) -> acc asegs m SA (4 * (n + 1)) -> wr_at asegs m DA (4 * n) -> acc asegs m DA (4 * n) -> mem_inv asegs m ->
  evt asegs (g2w_words_exit ra sp gp tp t0 t1 t2 s0 s1 a0 a3 a4 (Z_to_bv 64 2147450880) a7 s3 s4 s5 s6 t3 t4 t5 t6 F fc m DA n)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 (Z_to_bv 64 (DA + 4 * j)) (Z_to_bv 64 (SA + 4 * j)) a3 a4 (Z_to_bv 64 2147450880) (Z_to_bv 64 (SA + 4 * j + 4)) a7 s2 s3 s4 s5 s6 (Z_to_bv 64 (DA + 4 * j)) (Z_to_bv 64 (n - j)) s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x12ea00) fc None m (seg_rom asegs)).
