  fun ms' => exists (s0' s1' a1' a2' a3' a6' s2' s5' s6' s7' s8' s9' s10' s11' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0' s1' a0 a1' a2' a3' a4 a5 a6' a7 s2' s3 s4 s5' s6' s7' s8' s9' s10' s11' t3 t4 t5 t6)
             F (Z_to_bv 64 0x12d680) fc None m' (seg_rom asegs)
    /\ munch [(DR, DR + dn)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

(* [comment removed for export] *)
Lemma g2w_rows : forall (k : nat) (i : Z)
    (sp gp tp t0 t1 t2 a0 a1 a2 a4 a6 a7 s2 s7 s8 s9 s10 s11 t3 t4 t5 : word) F fc (m : mem)
    (dh n swpl dwpl PSF PDF SR sn DR dn : Z),
  Z.of_nat k = dh - i -> 0 <= i -> (1 <= k)%nat -> dh <= 20000 -> 1 <= n < 2^26 ->
  0 < swpl <= 2^20 -> 0 < dwpl <= 2^20 ->
  0 < SR -> SR mod 4 = 0 -> SR + sn <= 2^47 -> 0 < DR -> DR mod 4 = 0 -> DR + dn <= 2^47 -> PSF mod 4 = 0 -> PDF mod 4 = 0 ->
  (DR + dn <= 0x7fff7000 \/ 0x10007fff8000 <= DR) ->
  (forall i', 0 <= i' < dh -> SR <= PSF + 4 * (swpl * i') /\ PSF + 4 * (swpl * i') + 4 * (n + 1) <= SR + sn) ->
  (forall i', 0 <= i' < dh -> DR <= PDF + 4 * (dwpl * i') /\ PDF + 4 * (dwpl * i') + 4 * n <= DR + dn) ->
  wr_at asegs m SR sn -> acc asegs m SR sn -> wr_at asegs m DR dn -> acc asegs m DR dn -> mem_inv asegs m ->
  evt asegs (g2w_rows_exit (Z_to_bv 64 dh) sp gp tp t0 t1 t2 a0 a4 (Z_to_bv 64 2147450880) a7 (Z_to_bv 64 (dwpl * 4)) (Z_to_bv 64 (swpl * 4))
               t3 t4 t5 (Z_to_bv 64 n) F fc m DR dn)
    (MS (mkR (Z_to_bv 64 dh) sp gp tp t0 t1 t2 (Z_to_bv 64 (PDF + 4 * (dwpl * i))) (Z_to_bv 64 (PSF + 4 * (swpl * i))) a0 a1 a2 (Z_to_bv 64 i) a4 (Z_to_bv 64 2147450880) a6 a7 s2 (Z_to_bv 64 (dwpl * 4)) (Z_to_bv 64 (swpl * 4)) (Z_to_bv 64 (PSF + 4 * (swpl * i) + 4)) (Z_to_bv 64 (PDF + 4 * (dwpl * i))) s7 s8 s9 s10 s11 t3 t4 t5 (Z_to_bv 64 n))
        F (Z_to_bv 64 0x12e9e8) fc None m (seg_rom asegs)).
Proof.
